// 브랜드명으로 종합 채용사이트를 뒤지면 엉뚱한 회사가 무더기로 걸린다.
// 실제로 걸려 온 것들(2026-09 기준):
//   · 다른 회사 이름의 일부   순수해작 · 이엘렌탈 · 이엘치과 · 알루이엔씨 · 메이븐자산운용
//   · 글자만 겹침             순수미술 · 초순수 엔지니어링 · 히알루로니다제('알루'가 가운데)
//   · 같은 이름 다른 업종     끌로에(명품 패션) · 카페메이븐
//
// 두 가지로 거른다.
//   1) 낱말 경계 — 브랜드명 앞뒤에 한글·영문·숫자가 붙어 있으면 다른 낱말로 본다.
//   2) 뷰티 신호 — 종합 사이트(잡코리아·사람인)는 뷰티 어휘가 하나라도 있어야 통과.
// 둘을 AND 로 걸면 「리안헤어중산동점」 같은 진짜가 떨어져서, 경계는 뷰티 신호로
// 봐줄 수 있게 OR 로 묶는다.

const 뷰티어휘 = [
  "헤어", "미용", "살롱", "뷰티", "네일", "피부", "에스테틱", "메이크업", "왁싱",
  "속눈썹", "눈썹", "바버", "두피", "탈모", "스파", "마사지", "테라피", "네일아트",
  "디자이너", "미용사", "원장", "실장", "스텝", "스탭", "인턴", "스페어",
  "샵", "샵매니저", "아카데미", "화장품", "코스메틱", "성형", "피부과", "네일샵",
];

// 뷰티가 아닌 것이 확실한 자리. 브랜드명이 낱말로 딱 떨어져도(「헤라 매쓰 수학학원」,
// 「끌로에 신세계여주아울렛 판매사원」) 업종이 다르면 여기서 걸린다.
// 실제로 걸려 온 것을 보고 늘려 가는 목록이다 — 한 번에 다 적을 수는 없다.
const 아닌어휘 = [
  // 뷰티 어휘가 우연히 겹치는 자리
  "웹디자이너", "그래픽디자이너", "UI/UX", "UX디자이너", "퍼블리셔", "편집디자이너",
  // 확실히 다른 업종
  "학원", "강사", "컨벤션", "조리", "브런치", "부동산", "중개",
  "고객센터", "상담사", "텔레마케팅", "콜센터",
  "물류", "로지스", "택배", "배송", "창고",
  "렌탈", "치과", "건설", "커튼월", "창호", "공사관리", "안전관리", "안전감시",
  "자산운용", "펀드", "캐피탈", "저축은행", "인베스트",
  "제약", "엔지니어링", "생산기획", "에프앤비", "이엔씨", "아이엔씨",
  "주차", "경비", "청소", "편의점",
];

export function 아닌업종(text: string): boolean {
  const t = (text || "").replace(/\s+/g, "");
  return 아닌어휘.some((w) => t.includes(w.replace(/\s+/g, "")));
}

export function 뷰티신호(text: string): boolean {
  const t = (text || "").replace(/\s+/g, "");
  if (!t) return false;
  if (아닌업종(t)) return false;
  return 뷰티어휘.some((w) => t.includes(w));
}

// 브랜드명이 '낱말로' 들어 있는가. 앞뒤에 한글·영문·숫자가 이어지면 다른 낱말이다.
// 띄어쓰기·괄호·기호는 경계로 친다 — 공백을 지우고 보면 「[라운드랩] 법무팀장」의
// 멀쩡한 경계가 사라진다.
export function 낱말로들었나(text: string, brand: string): boolean {
  const t = (text || "").replace(/\s+/g, " ");
  const b = (brand || "").replace(/\s+/g, " ").trim();
  if (!b) return false;
  const 글자 = (c?: string) => !!c && /[가-힣A-Za-z0-9]/.test(c);
  let at = t.indexOf(b);
  while (at !== -1) {
    if (!글자(t[at - 1]) && !글자(t[at + b.length])) return true;
    at = t.indexOf(b, at + 1);
  }
  return false;
}

/**
 * 이 공고가 그 브랜드의 것인가.
 *
 * @param 종합사이트 잡코리아·사람인·알바몬처럼 뷰티 말고도 다 올라오는 곳이면 true.
 *   뷰티 전문 사이트(헤어인잡·뷰티잡·셀렉미)는 애초에 뷰티 공고뿐이라 묻지 않는다.
 *   자사 홈페이지도 그 회사 것이 확실하니 묻지 않는다.
 *
 * 낱말 경계(앞뒤에 한글이 붙었나)로도 걸러 봤는데, 한국어는 조사와 지점명이 이름에
 * 그대로 붙어서(「에이바이봄에서」·「로이드밤신정네거리역점」) 진짜를 더 많이 죽였다.
 * 뷰티 신호 하나만으로 순수해작·이엘렌탈·알루이엔씨·히알루로니다제·끌로에가 전부
 * 걸러지니 규칙을 늘리지 않는다.
 */
export function 브랜드공고인가(제목: string, 브랜드: string, 종합사이트: boolean): boolean {
  const t = 제목 || "";
  if (!t.replace(/\s+/g, "").includes((브랜드 || "").replace(/\s+/g, ""))) return false;
  if (!종합사이트) return true;
  // 업종이 확실히 다르면 브랜드명이 어떻게 박혀 있든 아니다.
  if (아닌업종(t)) return false;
  // 짧은 이름은 경계만으로 못 가른다 — 「헤라」는 그리스 신화 이름이라 PC방·
  // 노래타운·청소업체가 다 쓰고, 「순수」·「이엘」·「알루」도 마찬가지다.
  // 세 글자 이하는 뷰티 신호를 반드시 요구한다.
  const 짧은이름 = (브랜드 || "").replace(/\s+/g, "").length <= 3;
  if (짧은이름) return 뷰티신호(t);

  // 브랜드명이 낱말로 딱 떨어지거나(「[라운드랩] 법무팀장」), 붙어 있어도 뷰티
  // 신호가 있으면(「리안헤어중산동점 디자이너」) 그 브랜드로 본다.
  return 낱말로들었나(t, 브랜드) || 뷰티신호(t);
}
